(function(g){'use strict';var ORDER=['INGEST','M_T_ANALYSIS','AUDIT','FEATURE','ADMISSION','STATISTICS','PATTERN','METHOD_CHECK','EVIDENCE_GATE','AUTHOR_INTERVIEW','COMPOSITION','EVALUATION'];function state(caseId){return{schema:'HOOKLAB_ORCHESTRATOR_STATE_v0.1',case_id:caseId,stage:'INGEST',history:[],generation:'BLOCKED'}}function transition(s,next,payload){var a=ORDER.indexOf(s.stage),b=ORDER.indexOf(next);if(b<0||b>a+1)throw Error('INVALID_STAGE_TRANSITION');var h={from:s.stage,to:next,at:new Date().toISOString(),payload:payload||null};s.history.push(h);s.stage=next;return s}function evidenceNeed(target,stats){return{state:'INSUFFICIENT_EVIDENCE',target_relation:target,current_n_effective:stats&&stats.n_admitted||0,missing_context:'TO_BE_ESTIMATED_BY_METHOD_AGENT',recommended_action:'ANALYZE_AND_ADMIT_MORE_MATCHING_CASES',threshold_change_permitted:false}}function gate(request){if(!g.HookLabEvidenceGate)throw Error('EVIDENCE_GATE_REQUIRED');return g.HookLabEvidenceGate.authorize(request)}g.HookLabOrchestrator={version:'0.1',stages:ORDER.slice(),newState:state,transition:transition,evidenceNeed:evidenceNeed,authorize:g=>gate(g)}})(window);